INSERT INTO games (id, name, slug, publisher, category, cover_image_url, icon_url, so_giay_phep, ngay_cap_phep, description, instructions, redeem_url, is_active, updated_at)
VALUES ('tam-quoc-tu-thoi-ca', 'Tam Quốc Tứ Thời Ca', 'tam-quoc-tu-thoi-ca', 'SohaGame', 'Chiến Thuật & Thẻ Tướng', '/game_icons/tam-quoc-tu-thoi-ca.webp', '/game_icons/tam-quoc-tu-thoi-ca.webp', '383/QĐ-PTTH&TTĐT', '03/07/2026', 'Tam Quốc Tứ Thời Ca là siêu phẩm chiến thuật thẻ tướng quy tụ các danh tướng từ Tần - Hán - Đường trong thế giới Tam Quốc hoàn toàn mới của SohaGame. Tự do xây dựng đội hình, VAR xuyên thời đại và nhận trọn bộ 30+ giftcode độc quyền tháng 09/2026.', '1. Mở game Tam Quốc Tứ Thời Ca trên điện thoại hoặc giả lập.
2. Bấm vào biểu tượng Avatar góc trên bên trái màn hình.
3. Chọn mục Cài Đặt -> Chọn "Đổi Mã Quà" (Giftcode).
4. Nhập chính xác mã Giftcode và bấm "Xác Nhận" để nhận quà qua Hòm Thư ingame.', 'https://nap.sohagame.vn/tamquoctuthoica', 1, CURRENT_TIMESTAMP)
